<template>
  <component
    :is="href ? 'a' : clickable ? 'button' : 'div'"
    class="fu-card"
    :class="{
      'fu-card--bordered': bordered,
      'fu-card--flush': flush,
      'fu-card--clickable': href || clickable,
    }"
    :href="href || undefined"
    :type="!href && clickable ? 'button' : undefined"
    @click="onClick"
  >
    <header v-if="title || $slots.actions" class="fu-card__header">
      <h3 v-if="title" class="fu-card__title">{{ title }}</h3>
      <div v-if="$slots.actions" class="fu-card__actions" @click.stop>
        <slot name="actions" />
      </div>
    </header>

    <div class="fu-card__body">
      <slot />
    </div>
  </component>
</template>

<script setup lang="ts">
export interface FuCardProps {
  /** Small caps heading shown at the top of the card */
  title?: string;
  /** Draws the 1px Fusion border. Turn off when the card sits inside another bordered surface */
  bordered?: boolean;
  /** Removes the body padding so rows can run edge to edge (dividers inside are the rows' own) */
  flush?: boolean;
  /** Renders the whole card as a link */
  href?: string;
  /** Renders the whole card as a button and emits `click` */
  clickable?: boolean;
}

const props = withDefaults(defineProps<FuCardProps>(), {
  bordered: true,
  flush: false,
  clickable: false,
});

const emit = defineEmits<{ (e: "click", ev: MouseEvent): void }>();

function onClick(ev: MouseEvent) {
  if (props.clickable && !props.href) emit("click", ev);
}
</script>

