/**
 * Columns and cells: the column definitions handed to Tabulator, the cell formatter that draws cell slots
 * (and the rows the table adds to groups), and the cleanup of Vue content whose rows are gone.
 */
import { h, render, type VNode } from "vue";
import type { CellComponent, ColumnDefinition, RowComponent } from "tabulator-tables";
import type { TreeTableContext } from "./context";
import { createSorter, phantomIndex, phantomOf } from "./data";
import { drawGuides } from "./guides";
import { skeletonWidth } from "./skeleton";
import { levelOf } from "./tree";
import type { TreeTableColumn, TreeTableId } from "./types";

type RenderAddedCell = (wrap: HTMLElement, groupId: TreeTableId, onRendered: (fn: () => void) => void) => void;

const COL_GRIP_SVG =
    '<svg viewBox="0 0 16 16" width="12" height="12" aria-hidden="true"><g fill="currentColor"><circle cx="5.5" cy="3.5" r="1.2"/><circle cx="10.5" cy="3.5" r="1.2"/><circle cx="5.5" cy="8" r="1.2"/><circle cx="10.5" cy="8" r="1.2"/><circle cx="5.5" cy="12.5" r="1.2"/><circle cx="10.5" cy="12.5" r="1.2"/></g></svg>';

/** The expand/collapse arrow for rows with children. */
export function chevron(open: boolean): HTMLElement {
    const el = document.createElement("span");
    el.className = `fu-treetable__chevron${open ? " is-open" : ""}`;
    el.setAttribute("role", "button");
    el.setAttribute("aria-label", open ? "Collapse row" : "Expand row");
    el.innerHTML =
        '<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><path d="M6 3.5 10.5 8 6 12.5" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    return el;
}

export function useCells(
    ctx: TreeTableContext,
    added: { renderAddCell: RenderAddedCell; renderMoreCell: RenderAddedCell },
) {
    const { props, slots } = ctx;
    const sorter = createSorter(ctx);

    /** Header title with a grip that shows on hover, so it is clear the column can be dragged. */
    function headerTitle(label: string, movable = true): HTMLElement {
        const wrap = document.createElement("span");
        wrap.className = "fu-treetable__col-title";
        const grip = document.createElement("span");
        grip.className = `fu-treetable__col-grip${props.movableColumns && movable ? "" : " is-static"}`;
        grip.setAttribute("aria-hidden", "true");
        grip.innerHTML = COL_GRIP_SVG;
        wrap.appendChild(grip);
        const text = document.createElement("span");
        text.textContent = label;
        wrap.appendChild(text);
        return wrap;
    }

    /** A cell of a row the table added to a group (placeholder, "Show more", title), or null for a task row. */
    function addedCell(col: TreeTableColumn, data: Record<string, any>, onRendered: (fn: () => void) => void): HTMLElement | null {
        const kind = phantomOf(data);
        if (!kind) return null;
        /* A group's placeholder row: a shimmer bar in every cell */
        if (kind === "skeleton") {
            const bar = document.createElement("div");
            bar.className = "fu-treetable__skeleton-cell fu-treetable__phantom-skeleton";
            const colIndex = ctx.visibleColumns.value.findIndex((c) => c.key === col.key);
            bar.style.width = skeletonWidth(phantomIndex(ctx, data) + 1, colIndex);
            return bar;
        }
        /* "Show more" or the title row: the control in the tree column, nothing elsewhere (no cell slots) */
        const wrap = document.createElement("div");
        wrap.className = kind === "more" ? "fu-treetable__more-cell" : "fu-treetable__add-row-cell";
        if (col.key === ctx.treeKey.value) {
            const groupId = data[props.groupField as string];
            (kind === "more" ? added.renderMoreCell : added.renderAddCell)(wrap, groupId, onRendered);
        }
        return wrap;
    }

    function cellFormatter(col: TreeTableColumn) {
        return (cell: CellComponent, _params: unknown, onRendered: (fn: () => void) => void) => {
            const row = cell.getRow();
            const data = row.getData();
            const extra = addedCell(col, data, onRendered);
            if (extra) return extra;

            const slot = (slots as Record<string, any>)[`cell-${col.key}`];
            const value = cell.getValue();
            let out: HTMLElement;
            if (!slot) {
                out = document.createElement("span");
                out.className = "fu-treetable__text";
                out.textContent = value == null ? "" : String(value);
            } else {
                out = document.createElement("div");
                out.className = "fu-treetable__slot";
                const completed = !!props.rowCompleted?.(data);
                const vnode: VNode = h(
                    "span",
                    { class: "fu-treetable__slot-inner" },
                    slot({ row: data, value, level: levelOf(row), completed }),
                );
                ctx.mountVue(out, vnode);
                (out as HTMLElement & { __fuRowId?: TreeTableId }).__fuRowId = ctx.idOf(data);
            }
            if (col.key === ctx.treeKey.value) {
                /* Marks the task's name, so a complete task (rowCompleted) can be struck through */
                out.classList.add("fu-treetable__name");
                /* A small square before the name in the row's colour (rowColor, e.g. its status); CSS shows it only when the row has one */
                if (props.rowColor) {
                    const dot = document.createElement("span");
                    dot.className = "fu-treetable__row-color";
                    dot.setAttribute("aria-hidden", "true");
                    out.insertBefore(dot, out.firstChild);
                }
                const kids = data[props.childrenField];
                if (!Array.isArray(kids) || !kids.length) out.classList.add("fu-treetable__leaf");
                onRendered(() => drawGuides(ctx, cell));
            }
            return out;
        };
    }

    function buildColumns(): ColumnDefinition[] {
        let list = ctx.visibleColumns.value;
        const treeKey = ctx.treeKey.value;
        if (props.pinTreeColumn && treeKey) {
            const tree = list.find((c) => c.key === treeKey);
            if (tree) list = [tree, ...list.filter((c) => c !== tree)];
        }
        return list.map((col) => ({
            title: col.label,
            field: col.key,
            width: col.width,
            minWidth: col.minWidth ?? 80,
            hozAlign: col.textAlign ?? "left",
            headerHozAlign: col.textAlign ?? "left",
            headerSort: props.sortable && col.sortable !== false,
            headerSortStartingDir: "asc",
            resizable: props.resizableColumns && col.resizable !== false,
            frozen: props.pinTreeColumn && col.key === treeKey,
            ...(props.groupField || props.sortMode === "remote" ? { sorter: sorter as any } : {}),
            titleFormatter: () => headerTitle(col.label, !(props.pinTreeColumn && col.key === treeKey)),
            formatter: cellFormatter(col),
        }));
    }

    /**
     * Unmount Vue content whose element has left the page: rows scrolled away (with a fixed height, only
     * the rows on screen are drawn), rows in a closed group or under a closed task, and rows that are gone.
     * A row that's still in the table is marked to be drawn again, so Tabulator runs the cell formatters
     * when it comes back instead of re-attaching empty cells. That keeps the number of live slot
     * components to the rows on screen, however far the person scrolls.
     */
    function pruneDetached() {
        ctx.mounted.forEach((el) => {
            if (el.isConnected) return;
            render(null, el);
            ctx.mounted.delete(el);
            const row = (el.closest(".tabulator-row") as (HTMLElement & { __fuRow?: RowComponent }) | null)?.__fuRow;
            (row as any)?._row?.deinitialize?.();
        });
    }

    function unmountAllCells() {
        ctx.mounted.forEach((el) => render(null, el));
        ctx.mounted.clear();
    }

    return { buildColumns, pruneDetached, unmountAllCells };
}
