/**
 * The group headers (folders): chevron, colour square or avatar, title, meta line, count or total,
 * the group-extra slot, the "+" and "..." controls, and a shimmer while the group loads. Tabulator asks
 * for a header whenever it groups; each is drawn with Vue into an element Tabulator owns.
 */
import { h, render, type Component, type VNode } from "vue";
import type { GroupComponent } from "tabulator-tables";
import { Ellipsis, Plus } from "@lucide/vue";
import FusionActionButton from "../actionButton/FusionActionButton.vue";
import DropdownMenu from "../dropdownMenu/DropdownMenu.vue";
import FuAvatar from "../avatar/FuAvatar.vue";
import GroupColorSquare from "./parts/GroupColorSquare";
import type { GroupEl, TreeTableContext } from "./context";
import { isPhantom } from "./data";
import type { TreeTableGroup, TreeTableId } from "./types";

export const CHEVRON_SVG =
    '<svg viewBox="0 0 16 16" width="14" height="14"><path d="M6 3.5 10.5 8 6 12.5" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';

export function useGroupHeader(ctx: TreeTableContext, GroupDetailsTrigger: Component) {
    const { props, emit, slots } = ctx;

    /* The Vue-drawn header of each group, by group key. Tabulator draws a new header element whenever it
       groups again; the old one for that key is unmounted then, so nothing leaks. */
    const headerEls = new Map<TreeTableId, HTMLElement>();

    function unmountHeader(key: TreeTableId) {
        const el = headerEls.get(key);
        if (!el) return;
        render(null, el);
        headerEls.delete(key);
    }

    /** Unmounts the headers of groups that are no longer in `groups`. */
    function unmountRemovedHeaders() {
        const ids = new Set((props.groups ?? []).map((g) => g.id));
        [...headerEls.keys()].forEach((key) => !ids.has(key) && unmountHeader(key));
    }

    function unmountAllHeaders() {
        [...headerEls.keys()].forEach(unmountHeader);
    }

    /** The built-in "+" and "..." controls for a group bar. */
    function groupControls(key: TreeTableId, meta: TreeTableGroup): VNode[] {
        const out: VNode[] = [];
        if (props.groupAdd) {
            out.push(
                h(FusionActionButton, {
                    icon: Plus,
                    size: "sm",
                    variant: "ghost",
                    ariaLabel: props.groupAddLabel,
                    onClick: () => emit("add-task", { groupId: key }),
                }),
            );
        }
        const hidden: string[] = meta.hiddenActions ?? [];
        const list = (props.groupActions ?? []).filter((a) => !hidden.includes(a.key));
        if (list.length) {
            const actions = list.flatMap((a) => [
                ...(a.dividerBefore ? [{ type: "divider" as const }] : []),
                {
                    label: a.label,
                    icon: a.icon,
                    disabled: a.disabled,
                    onClick: () => emit("group-action", { groupId: key, action: a.key }),
                },
            ]);
            out.push(
                h(
                    DropdownMenu,
                    { actions, align: "left" },
                    {
                        trigger: () =>
                            h(FusionActionButton, { icon: Ellipsis, size: "sm", variant: "ghost", ariaLabel: "Actions" }),
                    },
                ),
            );
        }
        return out;
    }

    /** Colours on offer in the picker: the ones passed in, then any other group's colour. */
    function colorSwatches(): string[] {
        const used = (props.groups ?? []).map((g) => g.color).filter((c): c is string => !!c);
        return [...new Set([...(props.groupColors ?? []), ...used])];
    }

    /** The group's colour square (clickable with groupColorEditable). */
    function groupSquare(key: TreeTableId, meta: TreeTableGroup): VNode[] {
        if (props.groupColorEditable) {
            return [
                h(GroupColorSquare, {
                    color: meta.color ?? "",
                    swatches: colorSwatches(),
                    label: meta.label,
                    onChange: (color: string) => emit("group-color-change", { groupId: key, color }),
                }),
            ];
        }
        return meta.color
            ? [h("span", { class: "fu-treetable__group-color", style: { background: meta.color }, "aria-hidden": "true" })]
            : [];
    }

    /** The group's avatar (logo, else initials on its colour). The label sits next to it, so it's hidden from screen readers. */
    function groupAvatar(meta: TreeTableGroup): VNode | null {
        if (!meta.avatar) return null;
        return h("span", { class: "fu-treetable__group-avatar", "aria-hidden": "true" }, [
            h(FuAvatar, {
                src: meta.avatar.src || undefined,
                name: meta.avatar.name || meta.label,
                bg: meta.avatar.bg || meta.color,
                color: "#ffffff",
                alt: "",
                size: "xs",
                showStatus: false,
            }),
        ]);
    }

    /**
     * The avatar and name. With a `#group-details` slot they become a button that opens the group's
     * details card; the chevron and the rest of the header still open and close the group.
     */
    function groupTitle(key: TreeTableId, meta: TreeTableGroup): VNode {
        const avatar = groupAvatar(meta);
        const name = h("span", { class: "fu-treetable__group-name" }, meta.label);
        if (!(slots as Record<string, any>)["group-details"]) {
            return h("span", { class: "fu-treetable__group-title" }, avatar ? [avatar, name] : [name]);
        }
        return h(GroupDetailsTrigger, { groupKey: key, label: meta.label }, () => (avatar ? [avatar, name] : [name]));
    }

    /** The header's contents: a shimmer while loading, the app's #group slot, or the built-in parts. */
    function headerContent(key: TreeTableId, meta: TreeTableGroup, count: number, open: boolean) {
        const slot = (slots as Record<string, any>).group;
        const extra = (slots as Record<string, any>)["group-extra"];
        /* With lazy groups the header shows the group's real total, not just the rows loaded so far */
        const total = typeof meta.total === "number" ? meta.total : count;
        const chevronEl = h("span", { class: "fu-treetable__group-chevron", innerHTML: CHEVRON_SVG, "aria-hidden": "true" });
        if (meta.loading) {
            /* Loading: a shimmer in place of the square and the title */
            return [
                chevronEl,
                h("span", { class: "fu-treetable__group-shimmer fu-treetable__group-shimmer--square", "aria-hidden": "true" }),
                h("span", { class: "fu-treetable__group-shimmer fu-treetable__group-shimmer--title", "aria-hidden": "true" }),
                h("span", { class: "fu-treetable__visually-hidden" }, `Loading ${meta.label ?? ""}`),
            ];
        }
        if (slot) return slot({ group: meta, count, total, open });
        return [
            chevronEl,
            /* An avatar takes the colour square's place. Otherwise the square is rendered whenever there is a
               colour (or it can be set); groupStyle shows or hides it with CSS, so switching style needs no rebuild */
            ...(meta.avatar ? [] : groupSquare(key, meta)),
            groupTitle(key, meta),
            ...(meta.meta ? [h("span", { class: "fu-treetable__group-meta" }, meta.meta)] : []),
            h("span", { class: "fu-treetable__group-count" }, total.toLocaleString()),
            ...(extra ? [h("span", { class: "fu-treetable__group-extra" }, extra({ group: meta, count, total, open }))] : []),
            ...groupControls(key, meta),
        ];
    }

    /** Tabulator's groupHeader: the header element for one group. */
    function groupHeader(key: TreeTableId, count: number, group: GroupComponent): HTMLElement {
        const wrap = document.createElement("div") as GroupEl;
        wrap.className = "fu-treetable__group";
        wrap.__fuGroupId = key;
        /* Buttons inside the bar (add, menu, title) and anything in the group-extra slot must not open or close the group */
        wrap.addEventListener("click", (e) => {
            if ((e.target as HTMLElement).closest("button, a, input, select, textarea, .fu-treetable__group-extra, .fu-color-trigger")) {
                e.stopPropagation();
            }
        });
        const meta = ctx.groupById(key) ?? { id: key, label: String(key) };
        const open = group.getElement().classList.contains("tabulator-group-visible");
        /* Added rows (title, "Show more", placeholders) aren't tasks, so they aren't counted */
        try {
            count = group.getRows().filter((r) => !isPhantom(r.getData())).length;
        } catch {
            /* Tabulator's count stands */
        }
        const vnode: VNode = h("div", { class: "fu-treetable__group-inner" }, headerContent(key, meta, count, open));
        /* This group was drawn before: Tabulator replaced that header, so let its Vue content go */
        if (headerEls.get(key) !== wrap) unmountHeader(key);
        ctx.mountVue(wrap, vnode, false);
        headerEls.set(key, wrap);
        return wrap;
    }

    return { groupHeader, unmountRemovedHeaders, unmountAllHeaders };
}
