<template>
  <component
    :is="href ? 'a' : clickable ? 'button' : 'div'"
    class="fu-list-row"
    :class="{ 'fu-list-row--clickable': href || clickable, 'fu-list-row--divided': divided }"
    :href="href || undefined"
    :type="!href && clickable ? 'button' : undefined"
    @click="onClick"
  >
    <div v-if="$slots.leading" class="fu-list-row__leading">
      <slot name="leading" />
    </div>

    <div class="fu-list-row__body">
      <span class="fu-list-row__title">
        <slot>{{ title }}</slot>
      </span>
      <span v-if="subtitle || $slots.subtitle" class="fu-list-row__subtitle">
        <slot name="subtitle">{{ subtitle }}</slot>
      </span>
    </div>

    <div v-if="$slots.actions" class="fu-list-row__actions" @click.stop>
      <slot name="actions" />
    </div>
  </component>
</template>

<script setup lang="ts">
export interface FuListRowProps {
  /** Main line. Use the default slot instead for rich text (e.g. a bold name) */
  title?: string;
  /** Supporting line under the title. Use the `subtitle` slot for rich text */
  subtitle?: string;
  /** Draws a divider above every row except the first. Off = no lines at all */
  divided?: boolean;
  /** Renders the row as a link */
  href?: string;
  /** Renders the row as a button and emits `click` */
  clickable?: boolean;
}

const props = withDefaults(defineProps<FuListRowProps>(), {
  divided: true,
  clickable: false,
});

const emit = defineEmits<{ (e: "click", ev: MouseEvent): void }>();

function onClick(ev: MouseEvent) {
  if (props.clickable && !props.href) emit("click", ev);
}
</script>

