/**
 * Walking Tabulator's tree. The helpers tolerate rows whose tree data isn't set up yet (during a regroup
 * or a data swap), where Tabulator's own getTreeParent() throws.
 */
import type { RowComponent } from "tabulator-tables";
import type { TreeTableId } from "./types";

/** The row's tree parent, or null while Tabulator is still setting up its tree data */
export function treeParentOf(row: RowComponent): RowComponent | null {
    try {
        return (row.getTreeParent() as RowComponent) || null;
    } catch {
        return null;
    }
}

/** The row's tree children, or none while Tabulator is still setting up its tree data */
export function treeChildrenOf(row: RowComponent): RowComponent[] {
    try {
        return row.getTreeChildren() ?? [];
    } catch {
        return [];
    }
}

/** Calls `fn` on every row, children included. */
export function walk(rows: RowComponent[], fn: (r: RowComponent) => void) {
    rows.forEach((r) => {
        fn(r);
        walk(treeChildrenOf(r), fn);
    });
}

export function levelOf(row: RowComponent): number {
    let level = 0;
    let parent = treeParentOf(row);
    while (parent) {
        level++;
        parent = treeParentOf(parent);
    }
    return level;
}

export function siblingsOf(row: RowComponent): RowComponent[] {
    const parent = treeParentOf(row);
    return parent ? treeChildrenOf(parent) : [];
}

export function hasNextSibling(row: RowComponent, idOf: (r: Record<string, any>) => TreeTableId): boolean {
    const list = siblingsOf(row);
    const id = idOf(row.getData());
    const i = list.findIndex((r) => idOf(r.getData()) === id);
    return i > -1 && i < list.length - 1;
}

/** Whether `candidate` is `ancestor` or sits somewhere under it. */
export function isInside(candidate: RowComponent, ancestor: RowComponent, idOf: (r: Record<string, any>) => TreeTableId): boolean {
    let p: RowComponent | null = candidate;
    const id = idOf(ancestor.getData());
    while (p) {
        if (idOf(p.getData()) === id) return true;
        p = treeParentOf(p);
    }
    return false;
}

/** The group of a row: its top-level ancestor's `groupField` (subtasks don't carry it). */
export function groupOfRow(row: RowComponent, groupField?: string): TreeTableId | null {
    if (!groupField) return null;
    let root: RowComponent = row;
    let p = treeParentOf(root);
    while (p) {
        root = p;
        p = treeParentOf(root);
    }
    return root.getData()[groupField] ?? null;
}
