/**
 * Task rows: their state (colour square, strike-through, "just moved"), the drag grip, and drag and drop
 * to reorder or nest. A drop emits `row-move`; the parent moves the row in its own data.
 */
import type { RowComponent } from "tabulator-tables";
import type { GroupEl, TreeTableContext } from "./context";
import { phantomOf } from "./data";
import { groupOfRow, hasNextSibling, isInside, levelOf, treeChildrenOf, treeParentOf, walk } from "./tree";
import type { TreeTableDropPosition } from "./treeTableUtils";
import type { TreeTableId } from "./types";

const GRIP_SVG =
    '<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><g fill="currentColor"><circle cx="5.5" cy="3.5" r="1.2"/><circle cx="10.5" cy="3.5" r="1.2"/><circle cx="5.5" cy="8" r="1.2"/><circle cx="10.5" cy="8" r="1.2"/><circle cx="5.5" cy="12.5" r="1.2"/><circle cx="10.5" cy="12.5" r="1.2"/></g></svg>';

export type RowEl = HTMLElement & { __fuRow?: RowComponent };

export function useRows(ctx: TreeTableContext) {
    const { props, emit, host, idOf } = ctx;

    /* ---------- Row state ---------- */

    /* Each task row carries its own colour (rowColor, e.g. its status) for the square before its name, and is-completed (rowCompleted) */
    function setRowState(el: HTMLElement, row: RowComponent) {
        const color = (props.rowColor && props.rowColor(row.getData())) || "";
        if (color) el.style.setProperty("--fu-tt-row-color", color);
        else el.style.removeProperty("--fu-tt-row-color");
        el.classList.toggle("has-row-color", !!color);
        el.classList.toggle("is-completed", !!props.rowCompleted?.(row.getData()));
    }

    /** Re-applies the colour square and strike-through to the rows on the page (no cells are drawn again). */
    function refreshRowState() {
        host.value?.querySelectorAll<RowEl>(".tabulator-row").forEach((el) => {
            if (el.__fuRow) setRowState(el, el.__fuRow);
        });
    }

    /** Tabulator's rowFormatter. */
    function decorateRow(row: RowComponent) {
        const el = row.getElement() as RowEl;
        /* Added rows (title, "Show more", placeholders): no __fuRow (so they can't be dragged or dropped on), no grip, no colour */
        const kind = phantomOf(row.getData());
        if (kind) {
            el.classList.add("is-phantom", `is-${kind}-row`);
            return;
        }
        el.__fuRow = row;
        el.classList.toggle("is-moved", movedKey !== null && idOf(row.getData()) === movedKey);
        setRowState(el, row);
        if (!props.draggableRows) return;
        const header = el.querySelector(".tabulator-row-header");
        if (header && !header.querySelector(".fu-treetable__grip")) {
            const grip = document.createElement("span");
            grip.className = "fu-treetable__grip";
            grip.setAttribute("role", "button");
            grip.setAttribute("aria-label", "Drag to move task");
            grip.innerHTML = GRIP_SVG;
            header.insertBefore(grip, header.firstChild);
        }
    }

    /* ---------- Highlight the task that was just moved ---------- */

    let movedKey: TreeTableId | null = null;
    let movedTimer: ReturnType<typeof setTimeout> | null = null;

    function flashMoved(key: TreeTableId) {
        movedKey = key;
        if (movedTimer) clearTimeout(movedTimer);
        movedTimer = setTimeout(() => {
            movedKey = null;
            host.value?.querySelectorAll(".is-moved").forEach((n) => n.classList.remove("is-moved"));
        }, 2000);
    }

    function applyMovedHighlight() {
        const table = ctx.state.table;
        if (movedKey === null || !table) return;
        host.value?.querySelectorAll(".is-moved").forEach((n) => n.classList.remove("is-moved"));
        let hit: RowComponent | null = null;
        walk(table.getRows(), (r) => {
            if (idOf(r.getData()) === movedKey) hit = r;
        });
        if (!hit) return;
        const found: RowComponent = hit;
        found.getElement().classList.add("is-moved");
        /* Make sure the moved task is on screen, without jumping if it already is */
        found.scrollTo("nearest", false).catch(() => {});
    }

    /* ---------- Drag and drop (reorder and nest) ---------- */

    let dragRow: RowComponent | null = null;
    let dropTarget:
        | { kind: "row"; el: RowEl; row: RowComponent; position: TreeTableDropPosition }
        | { kind: "group"; el: HTMLElement; groupId: TreeTableId }
        | null = null;

    function clearDropClasses() {
        host.value?.querySelectorAll(".is-drop-inside, .is-line-top, .is-line-bottom, .is-dragging").forEach((n) => {
            n.classList.remove("is-drop-inside", "is-line-top", "is-line-bottom", "is-dragging");
            (n as HTMLElement).style.removeProperty("--fu-tt-line-x");
        });
    }

    function onGripDown(e: MouseEvent) {
        const grip = (e.target as HTMLElement).closest(".fu-treetable__grip");
        const rowEl = (e.target as HTMLElement).closest(".tabulator-row") as RowEl | null;
        if (grip && rowEl) rowEl.draggable = true;
    }

    function onGripUp() {
        host.value?.querySelectorAll<HTMLElement>(".tabulator-row[draggable=true]").forEach((r) => (r.draggable = false));
    }

    function onDragStart(e: DragEvent) {
        const rowEl = (e.target as HTMLElement).closest?.(".tabulator-row") as RowEl | null;
        if (!rowEl?.__fuRow || !rowEl.draggable) return;
        dragRow = rowEl.__fuRow;
        rowEl.classList.add("is-dragging");
        if (e.dataTransfer) {
            e.dataTransfer.effectAllowed = "move";
            e.dataTransfer.setData("text/plain", String(idOf(dragRow.getData())));
        }
    }

    function onDragOver(e: DragEvent) {
        if (!dragRow) return;
        const rowEl = (e.target as HTMLElement).closest?.(".tabulator-row") as RowEl | null;
        clearDropClasses();
        host.value?.querySelectorAll(".tabulator-row").forEach((n) => {
            if ((n as RowEl).__fuRow === dragRow) n.classList.add("is-dragging");
        });
        dropTarget = null;

        /* A group bar: dropping here puts the task first in that group */
        const groupEl = (e.target as HTMLElement).closest?.(".tabulator-group") as HTMLElement | null;
        if (groupEl) {
            const key = (groupEl.querySelector(".fu-treetable__group") as GroupEl | null)?.__fuGroupId;
            if (key !== undefined) {
                groupEl.classList.add("is-drop-inside");
                dropTarget = { kind: "group", el: groupEl, groupId: key };
                e.preventDefault();
                if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
            }
            return;
        }

        if (!rowEl?.__fuRow) return;

        const hovered = rowEl.__fuRow;
        const rect = rowEl.getBoundingClientRect();
        const ratio = (e.clientY - rect.top) / rect.height;
        const zone: TreeTableDropPosition = ratio < 0.28 ? "before" : ratio > 0.72 ? "after" : "inside";

        let target = hovered;
        let position: TreeTableDropPosition = zone;
        let lineLevel = levelOf(hovered);
        const edge: "top" | "bottom" = zone === "before" ? "top" : "bottom";

        if (zone === "after") {
            const kids = treeChildrenOf(hovered);
            if (kids.length && hovered.isTreeExpanded()) {
                /* Under an open parent means "first child", not "after the whole group" */
                target = kids[0];
                position = "before";
                lineLevel = levelOf(hovered) + 1;
            } else {
                /* Drag left to pull the task out to a higher level (as long as nothing follows it at that level) */
                const cell = rowEl.querySelector<HTMLElement>(`[tabulator-field="${ctx.treeKey.value}"]`);
                if (cell) {
                    const cellRect = cell.getBoundingClientRect();
                    const pad = parseFloat(getComputedStyle(cell).paddingLeft) || 0;
                    const wanted = Math.max(0, Math.round((e.clientX - (cellRect.left + pad)) / props.indent));
                    let cur = hovered;
                    let curLevel = lineLevel;
                    while (curLevel > wanted && !hasNextSibling(cur, idOf)) {
                        const up = treeParentOf(cur);
                        if (!up) break;
                        cur = up;
                        curLevel--;
                    }
                    target = cur;
                    lineLevel = curLevel;
                }
            }
        }

        if (isInside(target, dragRow, idOf)) return;

        if (position === "inside") {
            rowEl.classList.add("is-drop-inside");
        } else {
            const cell = rowEl.querySelector<HTMLElement>(`[tabulator-field="${ctx.treeKey.value}"]`);
            const pad = cell ? parseFloat(getComputedStyle(cell).paddingLeft) || 0 : 0;
            const x = cell ? cell.getBoundingClientRect().left - rect.left + pad + lineLevel * props.indent : 0;
            rowEl.style.setProperty("--fu-tt-line-x", `${x}px`);
            rowEl.classList.add(edge === "top" ? "is-line-top" : "is-line-bottom");
        }
        dropTarget = { kind: "row", el: rowEl, row: target, position };
        e.preventDefault();
        if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
    }

    /**
     * After a drop the rows change under a pointer that has not moved, and the browser keeps the old :hover
     * on whatever row now sits there. Hide hover styling until the pointer actually moves again.
     */
    function settleHover() {
        const el = host.value;
        if (!el) return;
        el.classList.add("is-settling");
        const clear = () => {
            el.classList.remove("is-settling");
            window.removeEventListener("pointermove", clear);
            window.removeEventListener("pointerdown", clear);
        };
        window.addEventListener("pointermove", clear, { once: true });
        window.addEventListener("pointerdown", clear, { once: true });
    }

    function onDrop(e: DragEvent) {
        if (!dragRow || !dropTarget) return;
        e.preventDefault();
        const source = dragRow;
        const fromParent = treeParentOf(source);
        flashMoved(idOf(source.getData()));
        settleHover();
        if (dropTarget.kind === "group") {
            emit("row-move", {
                id: idOf(source.getData()),
                targetId: null,
                position: "inside",
                fromParentId: fromParent ? idOf(fromParent.getData()) : null,
                toParentId: null,
                toGroupId: dropTarget.groupId,
            });
            onDragEnd();
            return;
        }
        const { row: target, position } = dropTarget;
        const toParent = position === "inside" ? target : treeParentOf(target);
        emit("row-move", {
            id: idOf(source.getData()),
            targetId: idOf(target.getData()),
            position,
            fromParentId: fromParent ? idOf(fromParent.getData()) : null,
            toParentId: toParent ? idOf(toParent.getData()) : null,
            ...(props.groupField ? { toGroupId: groupOfRow(target, props.groupField) } : {}),
        });
        /* The dragged row may already be gone when `dragend` fires, so reset here too */
        onDragEnd();
    }

    function onDragEnd() {
        dragRow = null;
        dropTarget = null;
        clearDropClasses();
        onGripUp();
    }

    const listeners: [string, (e: any) => void][] = [
        ["mousedown", onGripDown],
        ["mouseup", onGripUp],
        ["dragstart", onDragStart],
        ["dragover", onDragOver],
        ["drop", onDrop],
        ["dragend", onDragEnd],
    ];

    function bindDnd() {
        listeners.forEach(([name, fn]) => host.value?.addEventListener(name, fn));
    }

    function unbindDnd() {
        listeners.forEach(([name, fn]) => host.value?.removeEventListener(name, fn));
        if (movedTimer) clearTimeout(movedTimer);
    }

    return { decorateRow, refreshRowState, applyMovedHighlight, bindDnd, unbindDnd };
}
