/**
 * Applying the parent's changes to Tabulator: rows, groups, the groups' added rows, rowColor and
 * rowCompleted, and columns. Updates run one after another (two at once let a regroup delete a group
 * Tabulator was still drawing), and changes from the same tick are applied together ("Show more" changes
 * `rows` and the group's `more` at once; applying them separately would draw a 1,000-row table twice).
 * Groups the person closed stay closed, the scroll stays where it was, and the selection is kept.
 */
import { computed, nextTick, watch } from "vue";
import type { ColumnDefinition, GroupComponent } from "tabulator-tables";
import type { TreeTableContext } from "./context";
import { phantomSignatureOf, tableData } from "./data";
import { refreshGuides } from "./guides";
import { restoreScroll, scrollPositions } from "./scroll";
import type { TreeTableId } from "./types";

interface SyncDeps {
    buildColumns(): ColumnDefinition[];
    applySelection(): void;
    applyMovedHighlight(): void;
    refreshRowState(): void;
    focusAddRow(reveal?: boolean): void;
    focusMoreRow(): void;
    unmountRemovedHeaders(): void;
}

export function useSync(ctx: TreeTableContext, deps: SyncDeps) {
    const { props, state } = ctx;

    let updates: Promise<unknown> = Promise.resolve();
    function queueUpdate(fn: () => Promise<void>) {
        updates = updates.then(fn, fn);
        return updates;
    }

    /* ---------- Open and closed groups ---------- */

    /** Which groups are open now, by key, so a data swap or regroup can keep them that way. */
    function openGroups(): Map<TreeTableId, boolean> {
        return new Map((state.table?.getGroups() ?? []).map((g) => [g.getKey(), g.isVisible()] as [TreeTableId, boolean]));
    }

    let restoringGroups = false;
    /**
     * Regrouping opens every group again (groupStartOpen). Close again the ones that were closed; a group
     * that didn't exist before follows its `open`, else groupStartOpen. Only groups in the wrong state are
     * touched, because showing or hiding a group makes Tabulator group again.
     */
    function restoreOpenGroups(before: Map<TreeTableId, boolean>) {
        restoringGroups = true;
        try {
            state.table?.getGroups().forEach((g) => {
                const key = g.getKey();
                const shouldBeOpen = before.has(key) ? before.get(key)! : (ctx.groupById(key)?.open ?? props.groupStartOpen);
                if (g.isVisible() && !shouldBeOpen) g.hide();
                else if (!g.isVisible() && shouldBeOpen) g.show();
            });
        } finally {
            restoringGroups = false;
        }
    }

    /** Tabulator's groupVisibilityChanged: the person opened or closed a group (not the table restoring them). */
    function onGroupVisibilityChanged(group: GroupComponent, visible: boolean) {
        if (restoringGroups) return;
        ctx.emit("group-toggle", { groupId: group.getKey(), open: visible });
    }

    /* ---------- Rows and groups, gathered per tick ---------- */

    const pending = { rows: false, headers: false, phantoms: false, ids: false };
    let syncQueued = false;

    function scheduleSync(what: Partial<typeof pending>) {
        if (what.rows) pending.rows = true;
        if (what.headers) pending.headers = true;
        if (what.phantoms) pending.phantoms = true;
        if (what.ids) pending.ids = true;
        if (syncQueued) return;
        syncQueued = true;
        queueUpdate(flushSync);
    }

    async function flushSync() {
        syncQueued = false;
        const what = { ...pending };
        pending.rows = pending.headers = pending.phantoms = pending.ids = false;
        const t = state.table;
        if (!t || !state.built) return;
        const swapData = what.rows || what.phantoms;
        const before = openGroups();
        const saved = scrollPositions(ctx.host.value, state.holderEl);
        const root = ctx.host.value;
        if (root) root.style.minHeight = `${root.offsetHeight}px`;
        /* Swapping the data clears Tabulator's selection; that isn't the person unticking rows, so it isn't
           reported. applySelection() puts the selection back from selectedIds afterwards. */
        state.syncingSelection = true;
        try {
            if (props.groupField && (what.ids || (what.headers && !swapData))) {
                /* Headers of removed groups won't be drawn again */
                deps.unmountRemovedHeaders();
                /* Regrouping draws the headers again; the cells keep their content */
                t.setGroupValues(props.groups ? [props.groups.map((g) => g.id)] : ([] as any));
            }
            /* A data swap groups again too, so it also draws the headers */
            if (swapData) await t.replaceData(tableData(ctx));
            /* Keep the groups the person had closed closed */
            restoreOpenGroups(before);
        } finally {
            state.syncingSelection = false;
            restoreScroll(saved);
            if (root) root.style.minHeight = "";
        }
        deps.applySelection();
        await nextTick();
        /* Rows drawn while their tree data wasn't ready yet skipped their guide lines */
        refreshGuides(ctx);
        deps.applyMovedHighlight();
        if (what.rows) deps.focusAddRow(true);
        deps.focusMoreRow();
    }

    watch(
        () => props.rows,
        () => scheduleSync({ rows: true }),
        { deep: true },
    );

    /* Group changes (added, renamed, recoloured, moved, removed, a new total, loading). Only the headers are
       drawn again: the cells keep their content, because regrouping doesn't run the cell formatters again. */
    const groupIdsSignature = computed(() => JSON.stringify((props.groups ?? []).map((g) => g.id)));
    const groupSignature = computed(() =>
        JSON.stringify(
            (props.groups ?? []).map((g) => [
                g.id,
                g.label,
                g.color ?? "",
                g.hiddenActions ?? [],
                g.total ?? null,
                !!g.loading,
                g.meta ?? "",
                g.avatar ? [g.avatar.src, g.avatar.name, g.avatar.bg] : null,
            ]),
        ),
    );
    watch(groupIdsSignature, () => scheduleSync({ ids: true, headers: true }));
    watch(groupSignature, () => scheduleSync({ headers: true }));
    /* A group's added rows changed (it started or stopped loading, more rows were shown, groupAddRow): swap the data */
    watch(
        computed(() => phantomSignatureOf(ctx)),
        () => scheduleSync({ phantoms: true }),
    );

    /* ---------- rowColor and rowCompleted ---------- */

    /* Added or removed: the cells are drawn again, so the squares come or go. Two sources, not one getter
       returning [a, b]: a new array every time would count as a change on every render of the parent. */
    watch(
        [() => !!props.rowColor, () => !!props.rowCompleted],
        () =>
            queueUpdate(async () => {
                const t = state.table;
                if (!t || !state.built) return;
                t.setColumns(deps.buildColumns());
                await nextTick();
                deps.refreshRowState();
                deps.applySelection();
            }),
    );

    /*
     * A new function for rowColor or rowCompleted. An inline `(row) => …` in the parent's template is a new
     * function on every render of the parent, so this only re-applies the squares and strike-through; drawing
     * every cell again here would be slow, and loop if a cell slot makes the parent render.
     */
    watch(
        [() => props.rowColor, () => props.rowCompleted],
        () => deps.refreshRowState(),
    );

    /* ---------- Columns (label, width, visibility, order coming from the parent) ---------- */

    const columnSignature = computed(() =>
        JSON.stringify(ctx.visibleColumns.value.map((c) => [c.key, c.label, c.width, c.sortable, c.resizable, c.textAlign])),
    );
    watch(columnSignature, async () => {
        const t = state.table;
        if (!t || !state.built) return;
        t.setColumns(deps.buildColumns());
        await nextTick();
        deps.applySelection();
    });

    return { onGroupVisibilityChanged };
}
