/*
 * While a column header is dragged, shade the whole column so you can see it travelling. Tabulator
 * moves the column's cells live but only fires an event once you drop, so this watches for the
 * floating copy of the header it adds (".tabulator-moving") and marks that column's cells.
 */
import type { TreeTableContext } from "./context";

export function useColumnDrag(ctx: TreeTableContext) {
    let observer: MutationObserver | null = null;
    let shaded: HTMLElement[] = [];

    function markColumn(field: string | null) {
        shaded.forEach((el) => el.classList.remove("fu-treetable__col-dragging"));
        shaded = [];
        const table = ctx.state.table;
        if (!field || !table) return;
        // Cells carry no field name in the DOM, so ask Tabulator for the column's cells
        table
            .getColumn(field)
            ?.getCells()
            .forEach((c) => {
                const el = c.getElement();
                el.classList.add("fu-treetable__col-dragging");
                shaded.push(el);
            });
    }

    function watchColumnDrag() {
        if (!ctx.host.value || observer) return;
        observer = new MutationObserver((records) => {
            for (const r of records) {
                r.addedNodes.forEach((n) => {
                    if (n instanceof HTMLElement && n.classList.contains("tabulator-moving")) markColumn(n.getAttribute("tabulator-field"));
                });
                r.removedNodes.forEach((n) => {
                    if (n instanceof HTMLElement && n.classList.contains("tabulator-moving")) markColumn(null);
                });
            }
        });
        observer.observe(ctx.host.value, { childList: true, subtree: true });
    }

    function stopColumnDrag() {
        observer?.disconnect();
        observer = null;
    }

    return { watchColumnDrag, stopColumnDrag };
}
