/**
 * The tree connector lines: a vertical guide for each level that continues below, and the curved elbow
 * into the row.
 */
import type { CellComponent, RowComponent } from "tabulator-tables";
import type { TreeTableContext } from "./context";
import { hasNextSibling, levelOf, treeChildrenOf, treeParentOf, walk } from "./tree";

export const CHEVRON_SIZE = 20;

function makeLine(cls: string, style: Record<string, string>): HTMLElement {
    const el = document.createElement("span");
    el.className = cls;
    el.setAttribute("aria-hidden", "true");
    Object.assign(el.style, style);
    return el;
}

/** Draws the tree connector lines (vertical guides plus the curved elbow) for one row. */
export function drawGuides(ctx: TreeTableContext, cell: CellComponent) {
    const el = cell.getElement();
    el.querySelectorAll(".fu-treetable__guide, .fu-treetable__elbow").forEach((n) => n.remove());
    const row = cell.getRow();
    const level = levelOf(row);
    if (!level) return;

    const base = parseFloat(getComputedStyle(el).paddingLeft) || 0;
    const indent = ctx.props.indent;
    const x = (depth: number) => base + (depth - 1) * indent + CHEVRON_SIZE / 2;

    /* chain[0] is the top-level ancestor, chain[level] is this row */
    const chain: RowComponent[] = [row];
    let p = treeParentOf(row);
    while (p) {
        chain.unshift(p);
        p = treeParentOf(p);
    }

    for (let depth = 1; depth < level; depth++) {
        if (hasNextSibling(chain[depth], ctx.idOf)) {
            el.appendChild(makeLine("fu-treetable__guide", { left: `${x(depth)}px` }));
        }
    }

    const isParent = treeChildrenOf(row).length > 0;
    const run = indent - CHEVRON_SIZE / 2 + (isParent ? -2 : CHEVRON_SIZE - 4);
    if (hasNextSibling(row, ctx.idOf)) {
        el.appendChild(makeLine("fu-treetable__guide", { left: `${x(level)}px` }));
    }
    el.appendChild(makeLine("fu-treetable__elbow", { left: `${x(level)}px`, width: `${run}px` }));
}

/**
 * Draws the guide lines again on the rows that are on the page. Rows that aren't (scrolled away with a
 * fixed height, or in a closed group) are skipped: asking one for its cell makes Tabulator build the
 * whole row, cell slots included, and they get their lines when they're drawn anyway.
 */
export function refreshGuides(ctx: TreeTableContext) {
    const table = ctx.state.table;
    const key = ctx.treeKey.value;
    if (!table || !key) return;
    walk(table.getRows(), (r) => {
        if (!r.getElement()?.isConnected) return;
        const c = r.getCell(key);
        if (c) drawGuides(ctx, c);
    });
}
