<script setup lang="ts">
/**
 * FusionFrameGrid
 * A grid of pulled frames, photos or files. Tick the ones you want, and attach any of them to a task
 * from the "Attach to" menu on its card.
 */
import { computed, ref, type Component } from "vue";
import { Check, ChevronDown, Search } from "@lucide/vue";
import DropdownMenu from "../dropdownMenu/DropdownMenu.vue";

export interface FrameItem {
    id: string | number;
    name: string;
    /** Small text next to the name, for example "Desktop" or "Mobile". */
    kind?: string;
    /** Image URL. Without one a plain wireframe placeholder is drawn. */
    thumbnail?: string;
    /** A line under the card, for example "On: Hero section". */
    badge?: string;
    badgeTone?: "success" | "warning" | "muted";
    /** Names behind a short badge like "On 3 tasks". Shown in a small list when the badge is hovered or focused. */
    badgeList?: string[];
    /** Cannot be ticked or attached. */
    disabled?: boolean;
}

export interface FrameAttachTarget {
    id: string | number;
    label: string;
    /** Indent level, for subtasks. */
    level?: number;
    icon?: Component;
}

const props = withDefaults(
    defineProps<{
        items: FrameItem[];
        /** Ticked ids (v-model:selectedIds). */
        selectedIds?: (string | number)[];
        /** Where a frame can be attached. Shows the "Attach to" menu on each card. */
        attachTargets?: FrameAttachTarget[];
        /** Which targets each frame is already attached to, by frame id. Ticks them in the menu. */
        attachedTo?: Record<string | number, (string | number)[]>;
        columns?: number;
        selectable?: boolean;
        loading?: boolean;
        attachLabel?: string;
        /** Show a search box in the "Attach to" menu. "auto" turns it on when there are more than 5 targets. */
        attachSearch?: boolean | "auto";
        attachSearchPlaceholder?: string;
        emptyText?: string;
    }>(),
    {
        selectedIds: () => [],
        attachTargets: () => [],
        attachedTo: () => ({}),
        columns: 4,
        selectable: true,
        loading: false,
        attachLabel: "Attach to",
        attachSearch: "auto",
        attachSearchPlaceholder: "Search tasks",
        emptyText: "No frames yet. Pull a file to see them here.",
    },
);

const emit = defineEmits<{
    (e: "update:selectedIds", ids: (string | number)[]): void;
    /** A frame was attached to a target, or taken off it again. */
    (e: "attach", payload: { itemId: string | number; targetId: string | number; attached: boolean }): void;
    (e: "open", item: FrameItem): void;
}>();

const selected = computed(() => new Set(props.selectedIds));

function toggle(item: FrameItem) {
    if (item.disabled || !props.selectable) return;
    const next = new Set(props.selectedIds);
    if (next.has(item.id)) next.delete(item.id);
    else next.add(item.id);
    emit("update:selectedIds", [...next]);
}

const query = ref("");
const showSearch = computed(() => (props.attachSearch === "auto" ? props.attachTargets.length > 5 : props.attachSearch));

/**
 * The targets that match the search. A match keeps the targets above it (by level), so a subtask
 * still shows under its task.
 */
const visibleTargets = computed(() => {
    const q = query.value.trim().toLowerCase();
    if (!q) return props.attachTargets;
    const keep = new Set<number>();
    props.attachTargets.forEach((t, i) => {
        if (!t.label.toLowerCase().includes(q)) return;
        keep.add(i);
        let level = t.level ?? 0;
        for (let j = i - 1; j >= 0 && level > 0; j--) {
            const up = props.attachTargets[j].level ?? 0;
            if (up < level) {
                keep.add(j);
                level = up;
            }
        }
    });
    return props.attachTargets.filter((_, i) => keep.has(i));
});

function menuFor(item: FrameItem) {
    const here = props.attachedTo[item.id] ?? [];
    return visibleTargets.value.map((t) => ({
        label: `${"   ".repeat(t.level ?? 0)}${t.level ? "└ " : ""}${t.label}`,
        icon: t.icon,
        selected: here.includes(t.id),
        onClick: () => emit("attach", { itemId: item.id, targetId: t.id, attached: !here.includes(t.id) }),
    }));
}
</script>

<template>
    <div class="fu-framegrid" :style="{ '--fu-fg-cols': columns }">
        <template v-if="loading">
            <div v-for="n in columns * 2" :key="n" class="fu-framegrid__card is-skeleton">
                <div class="fu-framegrid__thumb" />
                <div class="fu-framegrid__line" />
                <div class="fu-framegrid__line fu-framegrid__line--short" />
            </div>
        </template>

        <template v-else>
            <div
                v-for="item in items"
                :key="item.id"
                class="fu-framegrid__card"
                :class="{ 'is-selected': selected.has(item.id), 'is-disabled': item.disabled }"
            >
                <button
                    type="button"
                    class="fu-framegrid__pick"
                    :disabled="item.disabled || !selectable"
                    :aria-pressed="selected.has(item.id)"
                    :aria-label="`${selected.has(item.id) ? 'Untick' : 'Tick'} ${item.name}`"
                    @click="toggle(item)"
                    @dblclick="emit('open', item)"
                >
                    <span class="fu-framegrid__thumb">
                        <slot name="thumb" :item="item">
                            <img v-if="item.thumbnail" :src="item.thumbnail" :alt="item.name" loading="lazy" />
                            <span v-else class="fu-framegrid__placeholder" aria-hidden="true">
                                <span class="fu-framegrid__ph-bar" />
                                <span class="fu-framegrid__ph-line" />
                                <span class="fu-framegrid__ph-block" />
                            </span>
                        </slot>
                        <span v-if="selectable" class="fu-framegrid__check" aria-hidden="true">
                            <Check :size="14" :stroke-width="3" />
                        </span>
                    </span>
                    <span class="fu-framegrid__meta">
                        <b class="fu-framegrid__name">{{ item.name }}</b>
                        <span v-if="item.kind" class="fu-framegrid__kind">{{ item.kind }}</span>
                    </span>
                </button>

                <span
                    v-if="item.badge"
                    class="fu-framegrid__badge"
                    :class="[`is-${item.badgeTone || 'success'}`, { 'has-list': item.badgeList?.length }]"
                    :tabindex="item.badgeList?.length ? 0 : undefined"
                    :aria-label="item.badgeList?.length ? `${item.badge}: ${item.badgeList.join(', ')}` : undefined"
                >
                    {{ item.badge }}
                    <span v-if="item.badgeList?.length" class="fu-framegrid__badge-list" role="tooltip">
                        <span v-for="n in item.badgeList" :key="n">{{ n }}</span>
                    </span>
                </span>

                <DropdownMenu
                    v-if="attachTargets.length && !item.disabled"
                    class="fu-framegrid__menu"
                    align="left"
                    :actions="menuFor(item)"
                    :content="showSearch"
                    :closeOnSelect="!showSearch"
                    @open="query = ''"
                >
                    <template v-if="showSearch" #content>
                        <label class="fu-framegrid__search" @click.stop>
                            <Search :size="14" aria-hidden="true" />
                            <input
                                v-model="query"
                                type="search"
                                :placeholder="attachSearchPlaceholder"
                                :aria-label="attachSearchPlaceholder"
                                @keydown.stop
                            />
                        </label>
                        <p v-if="!visibleTargets.length" class="fu-framegrid__search-empty">Nothing matches</p>
                    </template>
                    <template #trigger>
                        <span class="fu-framegrid__attach" role="button" tabindex="0">
                            {{ attachLabel }}
                            <ChevronDown :size="14" />
                        </span>
                    </template>
                </DropdownMenu>
            </div>

            <p v-if="!items.length" class="fu-framegrid__empty">
                <slot name="empty">{{ emptyText }}</slot>
            </p>
        </template>
    </div>
</template>

