/**
 * The group details card (#group-details slot): the group's title becomes a button that opens a card
 * under it. The card lives in FusionTreeTable's own template (teleported to the page), not in the header:
 * Tabulator draws headers again whenever it groups, and a card inside one would vanish or float at the
 * wrong place. It's anchored to the title button found by group key, so it follows the new header.
 */
import { computed, defineComponent, h, nextTick, ref, watch } from "vue";
import type { TreeTableContext } from "./context";
import type { TreeTableId } from "./types";

/** Whether the title can be seen: not scrolled out of the table, a tab body or any other clipping box. */
function anchorVisible(anchor: HTMLElement): boolean {
    const r = anchor.getBoundingClientRect();
    if (r.bottom <= 0 || r.top >= window.innerHeight || r.right <= 0 || r.left >= window.innerWidth) return false;
    let el = anchor.parentElement;
    while (el && el !== document.body) {
        const style = getComputedStyle(el);
        if (/(auto|scroll|hidden|clip)/.test(style.overflow + style.overflowX + style.overflowY)) {
            const box = el.getBoundingClientRect();
            if (r.bottom <= box.top || r.top >= box.bottom || r.right <= box.left || r.left >= box.right) return false;
        }
        el = el.parentElement;
    }
    return true;
}

export function useGroupDetails(ctx: TreeTableContext) {
    const detailsKey = ref<TreeTableId | null>(null);
    const detailsRef = ref<HTMLElement | null>(null);
    const detailsStyle = ref<Record<string, string>>({});
    const detailsGroup = computed(() => (detailsKey.value === null ? null : (ctx.groupById(detailsKey.value) ?? null)));

    function detailsAnchor(key: TreeTableId | null): HTMLElement | null {
        if (key === null || !ctx.host.value) return null;
        return (
            [...ctx.host.value.querySelectorAll<HTMLElement>("[data-fu-details-trigger]")].find(
                (el) => el.dataset.fuDetailsTrigger === String(key),
            ) ?? null
        );
    }

    function positionDetails() {
        const anchor = detailsAnchor(detailsKey.value);
        const card = detailsRef.value;
        if (!anchor || !card) return;
        /* The title scrolled out of view: close rather than float over something else */
        if (!anchorVisible(anchor)) return closeDetails(false);
        const r = anchor.getBoundingClientRect();
        const edge = 12;
        const gap = 6;
        const w = card.offsetWidth;
        const hgt = card.offsetHeight;
        let left = ctx.props.groupDetailsAlign === "right" ? r.right - w : r.left;
        left = Math.max(edge, Math.min(left, window.innerWidth - w - edge));
        let top = r.bottom + gap;
        if (top + hgt > window.innerHeight - edge && r.top - gap - hgt >= edge) top = r.top - gap - hgt;
        detailsStyle.value = { top: `${Math.round(top)}px`, left: `${Math.round(left)}px` };
    }

    function openDetails(key: TreeTableId) {
        if (detailsKey.value === key) return closeDetails();
        if (detailsKey.value !== null) closeDetails(false);
        detailsKey.value = key;
        ctx.emit("group-details-open", { groupId: key });
        nextTick(() => {
            positionDetails();
            /* Focus moves into the card: its first control, else the card itself */
            const card = detailsRef.value;
            const first = card?.querySelector<HTMLElement>(
                "button, a[href], input, select, textarea, [tabindex]:not([tabindex='-1'])",
            );
            (first ?? card)?.focus({ preventScroll: true });
        });
    }

    function closeDetails(refocus = true) {
        const key = detailsKey.value;
        if (key === null) return;
        detailsKey.value = null;
        ctx.emit("group-details-close", { groupId: key });
        if (refocus) detailsAnchor(key)?.focus({ preventScroll: true });
    }

    function onKeydown(e: KeyboardEvent) {
        if (e.key === "Escape" && detailsKey.value !== null) {
            e.stopPropagation();
            closeDetails();
        }
    }

    function onPointerDown(e: PointerEvent) {
        if (detailsKey.value === null) return;
        const target = e.target as Node;
        if (detailsRef.value?.contains(target)) return;
        /* A click on the title is the toggle itself */
        if (detailsAnchor(detailsKey.value)?.contains(target)) return;
        closeDetails(false);
    }

    function onViewportChange() {
        if (detailsKey.value !== null) positionDetails();
    }

    watch(detailsKey, (key) => {
        if (key !== null) {
            document.addEventListener("keydown", onKeydown, true);
            document.addEventListener("pointerdown", onPointerDown, true);
            window.addEventListener("scroll", onViewportChange, true);
            window.addEventListener("resize", onViewportChange);
        } else {
            document.removeEventListener("keydown", onKeydown, true);
            document.removeEventListener("pointerdown", onPointerDown, true);
            window.removeEventListener("scroll", onViewportChange, true);
            window.removeEventListener("resize", onViewportChange);
        }
    });

    /* The group the card belongs to was removed: close it */
    watch(
        () => ctx.props.groups,
        () => {
            if (detailsKey.value !== null && !ctx.groupById(detailsKey.value)) closeDetails(false);
        },
    );

    /** The group title as a button that opens the details card. */
    const GroupDetailsTrigger = defineComponent({
        props: {
            groupKey: { type: [String, Number], required: true },
            label: { type: String, default: "" },
        },
        setup(p, { slots }) {
            return () =>
                h(
                    "button",
                    {
                        type: "button",
                        class: "fu-treetable__group-title fu-treetable__group-title--button",
                        "data-fu-details-trigger": String(p.groupKey),
                        "aria-haspopup": "dialog",
                        "aria-expanded": detailsKey.value === p.groupKey ? "true" : "false",
                        onClick: () => openDetails(p.groupKey),
                    },
                    slots.default?.(),
                );
        },
    });

    /** After Tabulator redraws, the title is a new element: put the card back under it. */
    function repositionAfterRender() {
        if (detailsKey.value !== null) nextTick(positionDetails);
    }

    return { detailsRef, detailsStyle, detailsGroup, closeDetails, repositionAfterRender, GroupDetailsTrigger };
}
