<template>
  <div class="fu-module-menu-wrapper scrollbar__control customScrollBar">
    <div
      v-if="$slots.header || searchable"
      ref="headerRef"
      class="fu-module-menu-header"
      @keydown="onHeaderKeydown"
      @focusin="inputFocused = true"
      @focusout="inputFocused = false"
    >
      <slot name="header" />
      <div v-if="searchable" class="fu-module-menu-search">
        <FusionTextInput
          :modelValue="search"
          type="search"
          size="sm"
          variant="subtle"
          formWrapperWidth="100%"
          :placeholder="searchPlaceholder"
          @update:modelValue="onSearchInput"
        />
        <kbd
          v-if="searchShortcut && !search && !inputFocused"
          class="fu-module-menu-kbd"
          aria-hidden="true"
        >{{ searchShortcut }}</kbd>
      </div>
    </div>

    <ul v-show="!isSearching && !hideItems" class="fu-module-menu-wrapper__list">
      <template v-for="(group, groupIndex) in normalizedGroups" :key="groupIndex">
        <li
          v-if="groupIndex > 0 && (group.divider ?? !!group.title)"
          class="fu-module-menu-divider"
          role="separator"
        />
        <li v-if="group.title" class="fu-module-menu-group-title">{{ group.title }}</li>

        <li
          v-for="item in group.items"
          :key="item.path"
          :class="{ active: activePath && activePath.startsWith(item.path) }"
        >
          <router-link class="fu-module-menu-link" :to="item.path">
            <span class="fu-module-menu-link__start">
              <component
                v-if="item.icon"
                :is="item.icon"
                :size="15"
                class="fu-module-menu-icon"
              />
              <span>{{ item.label }}</span>
            </span>

            <FusionBadge
              v-if="item.badge !== undefined && item.badge !== null && item.badge !== ''"
              class="fu-module-menu-badge"
              :text="String(item.badge)"
              size="sm"
              :themeClass="item.badgeTheme || 'fu-badge--danger-subtle'"
            />
          </router-link>
        </li>
      </template>

      <li v-if="isEmpty" class="fu-module-menu-empty">No menu items</li>
    </ul>

    <!-- Search results: custom slot, or built-in label filter as fallback -->
    <div v-if="isSearching && $slots['search-results']" :id="resultsId">
      <slot name="search-results" :query="trimmedQuery" />
    </div>
    <ul
      v-else-if="isSearching"
      :id="resultsId"
      class="fu-module-menu-wrapper__list fu-module-menu-results"
      role="listbox"
      :aria-label="searchPlaceholder"
    >
      <template v-for="(group, groupIndex) in filteredGroups" :key="groupIndex">
        <li
          v-if="groupIndex > 0 && (group.divider ?? !!group.title)"
          class="fu-module-menu-divider"
          role="presentation"
        />
        <li v-if="group.title" class="fu-module-menu-group-title" role="presentation">
          {{ group.title }}
        </li>

        <li
          v-for="item in group.items"
          :id="optionId(item)"
          :key="item.path"
          role="option"
          :aria-selected="flatResults[highlightIndex] === item"
          :class="{
            active: activePath && activePath.startsWith(item.path),
            highlighted: flatResults[highlightIndex] === item,
          }"
        >
          <router-link class="fu-module-menu-link" :to="item.path">
            <span class="fu-module-menu-link__start">
              <component
                v-if="item.icon"
                :is="item.icon"
                :size="15"
                class="fu-module-menu-icon"
              />
              <span>{{ item.label }}</span>
            </span>

            <FusionBadge
              v-if="item.badge !== undefined && item.badge !== null && item.badge !== ''"
              class="fu-module-menu-badge"
              :text="String(item.badge)"
              size="sm"
              :themeClass="item.badgeTheme || 'fu-badge--danger-subtle'"
            />
          </router-link>
        </li>
      </template>

      <li v-if="!flatResults.length" class="fu-module-menu-empty" role="presentation">
        No results for “{{ trimmedQuery }}”
      </li>
    </ul>

    <!-- Custom slot after the list -->
    <slot />
  </div>
</template>

<script setup lang="ts">
import type { Component } from "vue";
import { computed, onBeforeUnmount, onMounted, ref, watch, watchEffect } from "vue";
import FusionBadge from "../badge/FusionBadge.vue";
import FusionTextInput from "../TextInput/FusionTextInput.vue";

interface MenuItem {
  label: string;
  path: string;
  icon?: Component;
  /** Count or label shown in a badge at the end of the item (e.g. 2, "4", "99+") */
  badge?: string | number;
  /** FusionBadge themeClass used to colour the badge, e.g. "fu-badge--danger-subtle" | "fu-badge--warning-subtle" */
  badgeTheme?: string;
}

interface MenuGroup {
  /** Optional section label rendered above the group, e.g. "DESK" or "ATTENTION STATES" */
  title?: string;
  /**
   * Show a horizontal rule above this group. Defaults to true when the group has a
   * title (and it isn't the first group) — set to false to show just the label with no rule.
   */
  divider?: boolean;
  items: MenuItem[];
}

const props = withDefaults(
  defineProps<{
    /** Flat list of menu items — ignored when `groups` is provided */
    items?: MenuItem[];
    /** Sectioned menu items, each with an optional title and divider */
    groups?: MenuGroup[];
    activePath?: string;
    /** Show a search input at the top of the menu */
    searchable?: boolean;
    /** Current search query. Use with `v-model:search` */
    search?: string;
    /** Placeholder text, also used as the input's aria-label */
    searchPlaceholder?: string;
    /** Key that focuses the search from anywhere on the page. `null` turns it off */
    searchShortcut?: string | null;
    /** Hide the item list (e.g. when the app renders its own search in the `header` slot) */
    hideItems?: boolean;
  }>(),
  {
    searchable: false,
    search: "",
    searchPlaceholder: "Search",
    searchShortcut: "/",
    hideItems: false,
  }
);

const emit = defineEmits<{
  (e: "update:search", value: string): void;
  (e: "search-keydown", event: KeyboardEvent): void;
}>();

const normalizedGroups = computed<MenuGroup[]>(() => {
  if (props.groups && props.groups.length) return props.groups;
  return [{ items: props.items || [] }];
});

const isEmpty = computed(() =>
  normalizedGroups.value.every((group) => !group.items || !group.items.length)
);

/* -----------------------------------------------------------
   Search
----------------------------------------------------------- */

const uid = Math.random().toString(36).slice(2, 9);
const resultsId = `fu-module-menu-results-${uid}`;

const headerRef = ref<HTMLElement | null>(null);
const inputFocused = ref(false);
const highlightIndex = ref(0);

const trimmedQuery = computed(() => (props.search ?? "").trim());
const isSearching = computed(() => props.searchable && trimmedQuery.value !== "");

const filteredGroups = computed<MenuGroup[]>(() => {
  const q = trimmedQuery.value.toLowerCase();
  return normalizedGroups.value
    .map((group) => ({
      ...group,
      items: (group.items || []).filter((item) => item.label.toLowerCase().includes(q)),
    }))
    .filter((group) => group.items.length);
});

const flatResults = computed(() => filteredGroups.value.flatMap((group) => group.items));

const optionId = (item: MenuItem) => `${resultsId}-opt-${flatResults.value.indexOf(item)}`;

const slots = defineSlots<{
  default?(): any;
  header?(): any;
  "search-results"?(props: { query: string }): any;
}>();

const usingFallback = computed(() => isSearching.value && !slots["search-results"]);

function getInput(): HTMLInputElement | null {
  return headerRef.value?.querySelector<HTMLInputElement>("input.fu-input") ?? null;
}

function focusSearch() {
  getInput()?.focus();
}

function onSearchInput(value: string | number) {
  emit("update:search", String(value ?? ""));
}

watch(trimmedQuery, () => {
  highlightIndex.value = 0;
});

function onHeaderKeydown(event: KeyboardEvent) {
  if (!props.searchable || event.target !== getInput()) return;
  emit("search-keydown", event);

  if (event.key === "Escape") {
    if (props.search) {
      emit("update:search", "");
    } else {
      getInput()?.blur();
    }
    return;
  }

  // ArrowUp / ArrowDown / Enter are never stopped, so a custom results slot can handle them.
  if (!usingFallback.value || !flatResults.value.length) return;
  const count = flatResults.value.length;

  if (event.key === "ArrowDown") {
    event.preventDefault();
    highlightIndex.value = (highlightIndex.value + 1) % count;
  } else if (event.key === "ArrowUp") {
    event.preventDefault();
    highlightIndex.value = (highlightIndex.value - 1 + count) % count;
  } else if (event.key === "Enter") {
    event.preventDefault();
    // Click the rendered router-link so navigation goes through the router as usual.
    const option = document.getElementById(`${resultsId}-opt-${highlightIndex.value}`);
    option?.querySelector<HTMLElement>("a")?.click();
  }
}

// The ARIA attributes are set directly on the <input> so they follow the live search state
// (FusionTextInput passes attributes to its <input> only, not its wrapper).
watchEffect(() => {
  const input = getInput();
  if (!input) return;
  const active = usingFallback.value && flatResults.value.length
    ? `${resultsId}-opt-${highlightIndex.value}`
    : null;
  input.setAttribute("role", "combobox");
  input.setAttribute("aria-label", props.searchPlaceholder);
  input.setAttribute("aria-expanded", String(isSearching.value));
  input.setAttribute("aria-controls", resultsId);
  input.setAttribute("aria-autocomplete", "list");
  if (active) input.setAttribute("aria-activedescendant", active);
  else input.removeAttribute("aria-activedescendant");
});

function onWindowKeydown(event: KeyboardEvent) {
  if (!props.searchable || !props.searchShortcut) return;
  if (event.key !== props.searchShortcut) return;
  if (event.metaKey || event.ctrlKey || event.altKey) return;

  const el = event.target as HTMLElement | null;
  if (el) {
    const tag = el.tagName;
    if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || el.isContentEditable) return;
  }

  event.preventDefault();
  focusSearch();
}

onMounted(() => window.addEventListener("keydown", onWindowKeydown));
onBeforeUnmount(() => window.removeEventListener("keydown", onWindowKeydown));

defineExpose({ focusSearch });
</script>

<style scoped lang="scss">
@import url("./FusionModuleMenu.scss");
</style>
